def resolve_asset_path(filename: str) -> str:
    """Hero asset dosyasını Windows + Streamlit çalışma senaryolarında güvenli bulur."""
    from pathlib import Path
    import glob

    wanted_stem = Path(filename).stem.lower()
    wanted_suffix = Path(filename).suffix.lower()

    start_points = []

    try:
        start_points.append(Path(__file__).resolve().parent)
    except Exception:
        pass

    try:
        start_points.append(Path.cwd().resolve())
    except Exception:
        pass

    try:
        start_points.append(Path(_APP_DIR).resolve())
    except Exception:
        pass

    try:
        start_points.append(Path.home().resolve())
    except Exception:
        pass

    candidates = []

    # Normal olası yollar
    for start in start_points:
        for base in [start, *start.parents]:
            candidates.extend([
                base / "assets" / filename,
                base / "karma_app" / "assets" / filename,
                base / "Startkey_Talep_Sistemi" / "karma_app" / "assets" / filename,
                base / filename,
            ])

    # Windows kullanıcı klasörleri: C:/Users/* altında doğrudan ara
    windows_patterns = [
        r"C:\Users\*\Startkey_Talep_Sistemi\karma_app\assets\sunum_hero_film*.png",
        r"C:\Users\*\Startkey_Talep_Sistemi\karma_app\assets\*hero*film*.png",
        r"C:\Users\*\Startkey_Talep_Sistemi\karma_app\assets\*.png",
    ]
    for pattern in windows_patterns:
        try:
            for match in glob.glob(pattern):
                candidates.append(Path(match))
        except Exception:
            pass

    # Önce birebir var mı?
    seen = set()
    for candidate in candidates:
        try:
            c = str(candidate)
            if c in seen:
                continue
            seen.add(c)
            if candidate.exists() and candidate.is_file() and candidate.name.lower() == filename.lower():
                return c
        except Exception:
            continue

    # Sonra küçük ad farklarını yakala: boşluk, tire, parantez, büyük/küçük harf
    seen = set()
    for candidate in candidates:
        try:
            c = str(candidate)
            if c in seen:
                continue
            seen.add(c)
            if not (candidate.exists() and candidate.is_file()):
                continue
            normalized_name = candidate.stem.lower().replace(" ", "").replace("-", "_")
            normalized_wanted = wanted_stem.replace(" ", "").replace("-", "_")
            if candidate.suffix.lower() == wanted_suffix and (
                normalized_name == normalized_wanted
                or "sunum" in normalized_name and "hero" in normalized_name and "film" in normalized_name
            ):
                return c
        except Exception:
            continue

    # Bulamazsa en olası doğru yeri döndürür; ekranda uyarı basılır.
    try:
        return str(Path(__file__).resolve().parent.parent / "assets" / filename)
    except Exception:
        return os.path.join(_APP_DIR, "assets", filename)


def asset_debug_text(filename: str) -> str:
    """Gerekirse hangi klasörlerin kontrol edildiğini göstermek için kısa debug metni."""
    from pathlib import Path
    import glob

    checked = []
    try:
        checked.append(str(Path(__file__).resolve().parent.parent / "assets" / filename))
    except Exception:
        pass
    try:
        checked.append(str(Path.cwd().resolve() / "karma_app" / "assets" / filename))
        checked.append(str(Path.cwd().resolve() / "assets" / filename))
    except Exception:
        pass
    try:
        checked.append(str(Path.home().resolve() / "Startkey_Talep_Sistemi" / "karma_app" / "assets" / filename))
    except Exception:
        pass

    try:
        matches = glob.glob(r"C:\Users\*\Startkey_Talep_Sistemi\karma_app\assets\*.png")
        checked.extend(matches[:12])
    except Exception:
        pass

    compact = []
    seen = set()
    for item in checked:
        if item not in seen:
            compact.append(item)
            seen.add(item)

    return "<br>".join(compact[:18])


