def h(v: Any) -> str:
    return html.escape("" if v is None else str(v))


def safe(v: Any, default: str = "") -> str:
    if v is None:
        return default
    text = str(v).strip()
    return text if text else default


def clean_phone(v: Any) -> str:
    txt = safe(v)
    return "".join(ch for ch in txt if ch.isdigit() or ch == "+")


def price_fmt(v: Any) -> str:
    txt = safe(v)
    if not txt:
        return "Fiyat belirtilmedi"
    if "₺" in txt or "TL" in txt.upper():
        return txt
    try:
        raw = txt.replace(".", "").replace(",", ".").replace(" ", "")
        n = float(raw)
        return f"{n:,.0f} TL".replace(",", ".")
    except Exception:
        return txt


def short_text(txt: Any, limit: int = 92) -> str:
    s = safe(txt)
    if len(s) <= limit:
        return s
    return s[: limit - 1].rstrip() + "…"


