def get_font(size: int, bold: bool = False) -> ImageFont.FreeTypeFont:
    candidates = []
    if bold:
        candidates = [
            "C:/Windows/Fonts/arialbd.ttf",
            "C:/Windows/Fonts/segoeuib.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
            "/System/Library/Fonts/Supplemental/Arial Bold.ttf",
        ]
    else:
        candidates = [
            "C:/Windows/Fonts/arial.ttf",
            "C:/Windows/Fonts/segoeui.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/System/Library/Fonts/Supplemental/Arial.ttf",
        ]
    for path in candidates:
        try:
            return ImageFont.truetype(path, size)
        except Exception:
            pass
    try:
        return ImageFont.load_default(size=size)
    except Exception:
        return ImageFont.load_default()


def hex_to_rgb(hex_color: str) -> Tuple[int, int, int]:
    c = (hex_color or "#000000").strip().lstrip("#")
    if len(c) == 3:
        c = "".join([x * 2 for x in c])
    try:
        return tuple(int(c[i : i + 2], 16) for i in (0, 2, 4))  # type: ignore[return-value]
    except Exception:
        return (0, 0, 0)


def with_alpha(hex_color: str, alpha: int) -> Tuple[int, int, int, int]:
    r, g, b = hex_to_rgb(hex_color)
    return (r, g, b, alpha)


def image_to_data_uri(img: Image.Image, fmt: str = "JPEG", quality: int = 86) -> str:
    buf = io.BytesIO()
    if fmt.upper() == "JPEG":
        img.convert("RGB").save(buf, format="JPEG", quality=quality)
        mime = "image/jpeg"
    else:
        img.save(buf, format="PNG")
        mime = "image/png"
    return f"data:{mime};base64," + base64.b64encode(buf.getvalue()).decode("utf-8")


def bytes_to_data_uri(raw: bytes, mime: str = "image/png") -> str:
    return f"data:{mime};base64," + base64.b64encode(raw).decode("utf-8")


def pil_to_png_bytes(img: Image.Image) -> bytes:
    buf = io.BytesIO()
    img.save(buf, format="PNG")
    return buf.getvalue()


def fit_cover(img: Image.Image, size: Tuple[int, int]) -> Image.Image:
    img = img.convert("RGB")
    return ImageOps.fit(img, size, method=Image.LANCZOS, centering=(0.5, 0.5))


def fit_cover_face(img: Image.Image, size: Tuple[int, int]) -> Image.Image:
    """Yüz fotoğrafları için — görseli önce dikey oranlı kırpar, sonra kare yapar."""
    w, h = img.size
    target_w, target_h = size
    # Görselin en-boy oranına göre yüz pozisyonunu tahmin et
    aspect = w / max(h, 1)
    if aspect < 0.8:
        # Dikey/portre fotoğraf → yüz üst %35'te
        centering_y = 0.15
    elif aspect > 1.3:
        # Yatay fotoğraf → yüz ortada
        centering_y = 0.3
    else:
        # Kare yakın → üst %25
        centering_y = 0.2
    return ImageOps.fit(img, size, method=Image.LANCZOS, centering=(0.5, centering_y))


def fit_contain(img: Image.Image, size: Tuple[int, int], bg: str = "#ffffff") -> Image.Image:
    img = img.convert("RGB")
    canvas_img = Image.new("RGB", size, hex_to_rgb(bg))
    copy = img.copy()
    copy.thumbnail(size, Image.LANCZOS)
    x = (size[0] - copy.size[0]) // 2
    y = (size[1] - copy.size[1]) // 2
    canvas_img.paste(copy, (x, y))
    return canvas_img


def rounded_rectangle(draw: ImageDraw.ImageDraw, xy: Tuple[int, int, int, int], radius: int, fill: Any, outline: Any = None, width: int = 1) -> None:
    try:
        draw.rounded_rectangle(xy, radius=radius, fill=fill, outline=outline, width=width)
    except Exception:
        draw.rectangle(xy, fill=fill, outline=outline, width=width)


def draw_text(draw: ImageDraw.ImageDraw, xy: Tuple[int, int], text: str, font: ImageFont.ImageFont, fill: Any, anchor: Optional[str] = None) -> None:
    try:
        draw.text(xy, text, font=font, fill=fill, anchor=anchor)
    except TypeError:
        draw.text(xy, text, font=font, fill=fill)


def text_width(draw: ImageDraw.ImageDraw, text: str, font: ImageFont.ImageFont) -> int:
    try:
        box = draw.textbbox((0, 0), text, font=font)
        return box[2] - box[0]
    except Exception:
        return len(text) * 10


def wrap_lines(draw: ImageDraw.ImageDraw, text: str, font: ImageFont.ImageFont, max_width: int, max_lines: int = 3) -> List[str]:
    words = safe(text).split()
    if not words:
        return [""]
    lines: List[str] = []
    cur = ""
    for word in words:
        candidate = (cur + " " + word).strip()
        if text_width(draw, candidate, font) <= max_width:
            cur = candidate
        else:
            if cur:
                lines.append(cur)
            cur = word
            if len(lines) >= max_lines:
                break
    if cur and len(lines) < max_lines:
        lines.append(cur)
    if len(lines) == max_lines and len(" ".join(words)) > len(" ".join(lines)):
        lines[-1] = lines[-1].rstrip("…") + "…"
    return lines


def placeholder_image(size: Tuple[int, int], label: str = "STARTKEY ZETA") -> Image.Image:
    img = Image.new("RGB", size, (245, 247, 250))
    d = ImageDraw.Draw(img)
    primary = (39, 39, 127)
    rounded_rectangle(d, (size[0] // 6, size[1] // 3, size[0] * 5 // 6, size[1] * 2 // 3), 22, (255, 255, 255), outline=(225, 229, 235), width=2)
    draw_text(d, (size[0] // 2, size[1] // 2 - 10), label, get_font(max(18, size[0] // 22), True), primary, anchor="mm")
    draw_text(d, (size[0] // 2, size[1] // 2 + 28), "Görsel bulunamadı", get_font(max(12, size[0] // 34)), (107, 114, 128), anchor="mm")
    return img


def load_image_from_url(url: str, timeout: int = 6) -> Optional[Image.Image]:
    if not url:
        return None
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read()
        return Image.open(io.BytesIO(raw)).convert("RGB")
    except Exception:
        return None


def load_image_from_bytes(raw: Optional[bytes]) -> Optional[Image.Image]:
    if not raw:
        return None
    try:
        return Image.open(io.BytesIO(raw)).convert("RGB")
    except Exception:
        return None


