def extract_photos(row: Dict[str, Any]) -> List[Dict[str, Any]]:
    photos: List[Dict[str, Any]] = []
    candidates = [
        "foto_url", "foto_urls", "image_urls", "ilk_foto_url", "images", "photo_urls",
        "gorsel", "gorseller", "resim", "resimler", "fotograflar",
    ]
    seen = set()
    for key in candidates:
        value = row.get(key)
        if isinstance(value, str):
            # JSON benzeri alanları kaba şekilde parçala
            bits = re.findall(r"https?://[^\s,'\"]+", value) if "http" in value and ("[" in value or "," in value) else [value]
            for item in bits:
                item = item.strip().strip("'\"")
                if item and item not in seen:
                    seen.add(item)
                    photos.append({"key": f"url_{len(photos)}", "url": item, "name": f"Fotoğraf {len(photos)+1}"})
        elif isinstance(value, (list, tuple)):
            for item in value:
                if isinstance(item, str) and item.strip() and item.strip() not in seen:
                    seen.add(item.strip())
                    photos.append({"key": f"url_{len(photos)}", "url": item.strip(), "name": f"Fotoğraf {len(photos)+1}"})
                elif isinstance(item, dict):
                    u = item.get("url") or item.get("src") or item.get("foto_url") or item.get("image_url")
                    if u and u not in seen:
                        seen.add(u)
                        photos.append({"key": f"url_{len(photos)}", "url": u, "name": item.get("name") or f"Fotoğraf {len(photos)+1}"})
    return photos


def normalize_record(row: Dict[str, Any]) -> Dict[str, Any]:
    profile = get_profile()
    title = (
        row.get("baslik") or row.get("ilan_basligi") or row.get("title") or row.get("ozet") or
        " ".join([safe(row.get("islem_tipi")), safe(row.get("mulk_tipi")), safe(row.get("ilce"))]).strip() or
        "Portföy kaydı"
    )
    il = safe(row.get("il") or row.get("city"))
    ilce = safe(row.get("ilce") or row.get("district"))
    mahalle = safe(row.get("mahalle") or row.get("neighborhood"))
    location_parts = [p for p in [il, ilce, mahalle] if p]
    location = ", ".join(location_parts) or safe(row.get("konum") or row.get("adres"), "Konum belirtilmedi")

    danisman = (
        row.get("danisman") or row.get("danisman_ad") or row.get("danisman_adi") or
        row.get("talep_eden_danisan") or row.get("gonderen") or profile.get("ad")
    )
    telefon = (
        row.get("telefon") or row.get("danisman_tel") or row.get("danisman_telefon") or
        row.get("cep_tel") or profile.get("telefon")
    )
    photos = extract_photos(row)

    norm = {
        "id": safe(row.get("id") or row.get("ilan_no") or row.get("portfoy_id") or row.get("uuid") or str(abs(hash(str(row))) % 10_000_000)),
        "raw": row,
        "title": safe(title, "Portföy kaydı"),
        "baslik": safe(title, "Portföy kaydı"),
        "price": safe(row.get("fiyat") or row.get("price") or row.get("bedel") or row.get("butce")),
        "fiyat": safe(row.get("fiyat") or row.get("price") or row.get("bedel") or row.get("butce")),
        "islem_tipi": safe(row.get("islem_tipi") or row.get("durum") or row.get("listing_type"), "Satılık"),
        "mulk_tipi": safe(row.get("mulk_tipi") or row.get("kategori") or row.get("property_type"), "Konut"),
        "il": il,
        "ilce": ilce,
        "mahalle": mahalle,
        "location": location,
        "konum": location,
        "m2": safe(row.get("m2") or row.get("metrekare") or row.get("brut_m2") or row.get("net_m2")),
        "oda": safe(row.get("oda") or row.get("oda_sayisi") or row.get("rooms")),
        "oda_sayisi": safe(row.get("oda") or row.get("oda_sayisi") or row.get("rooms")),
        "kat": safe(row.get("kat") or row.get("floor")),
        "bina_yasi": safe(row.get("bina_yasi") or row.get("yas") or row.get("age")),
        "danisman": safe(danisman, profile.get("ad", "Gayrimenkul Danışmanı")),
        "telefon": safe(telefon),
        "aciklama": safe(row.get("aciklama") or row.get("description") or row.get("not") or row.get("ozet")),
        "ilan_linki": safe(row.get("ilan_linki") or row.get("url") or row.get("link")),
        "kaynak": safe(row.get("kaynak") or row.get("source")),
        "photos": photos,
        "features": [],
    }

    features = []
    for item in [norm["m2"] and f"{norm['m2']} m²", norm["oda"], norm["kat"], norm["bina_yasi"] and f"{norm['bina_yasi']} yaş"]:
        if item:
            features.append(item)
    extra = row.get("ozellikler") or row.get("etiketler") or row.get("features") or []
    if isinstance(extra, str):
        features.extend([x.strip() for x in re.split(r"[,\n;]", extra) if x.strip()])
    elif isinstance(extra, (list, tuple)):
        features.extend([safe(x) for x in extra if safe(x)])
    norm["features"] = features[:10]
    return norm


@st.cache_data(ttl=90, show_spinner=False)
def load_records_from_supabase(source: str, user_name: str = "") -> List[Dict[str, Any]]:
    if get_client is None:
        return []
    try:
        supabase = get_client()
        q = supabase.table("portfoyler").select("*")
        if source == "ZETA Ofis":
            try:
                q = q.in_("kaynak", ["zeta1", "zeta2", "ZETA1", "ZETA2"])
            except Exception:
                pass
        elif source == "Benim Portföylerim" and user_name:
            # Kolon adları projeye göre değişebileceği için önce yumuşak filtreyi Python tarafında yapacağız.
            pass
        res = q.limit(400).execute()
        data = getattr(res, "data", []) or []
        if source == "Benim Portföylerim" and user_name:
            uname = user_name.lower().strip()
            data = [r for r in data if uname and uname in safe(r.get("danisman") or r.get("danisman_ad") or r.get("danisman_adi")).lower()]
        return [normalize_record(r) for r in data]
    except Exception:
        return []


