def current_records() -> List[Dict[str, Any]]:
    source = st.session_state.get("smv2_record_source", "ZETA Ofis")
    user_name = get_profile().get("ad", "")
    records = load_records_from_supabase(source, user_name=user_name)
    # Favorilerim şimdilik session'daki seçili kaydı veya demo kaydı gösterir.
    if source == "Favorilerim":
        fav = st.session_state.get("smv2_favorite_records", [])
        records = [normalize_record(x) for x in fav] if fav else []
