            loc_txt = short_text(location, 34)

            # Kutu boyutları
            box_x    = 50
            box_y    = info_y_start + 30
            box_w    = W - 100
            box_h    = 280
            box_img  = Image.new("RGBA", (box_w, box_h), (0, 0, 0, 0))
            box_d    = ImageDraw.Draw(box_img)
            box_d.rounded_rectangle((0, 0, box_w - 1, box_h - 1),
                                    radius=18,
                                    fill=(pr, pg, pb, 155))  # şeffaf lacivert
            # Sol kırmızı kenar çizgisi
            box_d.rounded_rectangle((0, 0, 6, box_h - 1), radius=3,
                                    fill=(215, 25, 32, 255))
            canvas_img.paste(box_img, (box_x, box_y), box_img)

            bd2 = ImageDraw.Draw(canvas_img)

            # Kategori başlığı — kutu içinde üstte
            kat_font = get_font(26, True)
