    if style in {"modern_post", "dark_post"}:
        dark = style == "dark_post"
        canvas_img = Image.new("RGB", (W, H), hex_to_rgb(primary) if dark else (255, 255, 255))
        d = ImageDraw.Draw(canvas_img)
        photo_box = (90, 130, W - 90, 610)
