def render_pdf_bytes_self(record: Dict[str, Any], photos: List[Image.Image], palette: Dict[str, str], template: TemplateSpec) -> bytes:
    if not REPORTLAB_OK:
        # Reportlab yoksa HTML dosyasını PDF yerine açıklayıcı fallback olarak döndürmeyelim; çağıran uyarı verecek.
        raise RuntimeError("reportlab kurulu değil. PDF üretimi için requirements'a reportlab ekleyin.")

    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=A4)
    page_w, page_h = A4
    primary = palette["primary"]
    secondary = palette["secondary"]
    soft = palette["soft"]

    def draw_pil(img: Image.Image, x: float, y: float, w: float, h_: float) -> None:
        tmp = io.BytesIO()
        fit_cover(img, (int(w * 3), int(h_ * 3))).save(tmp, format="JPEG", quality=86)
        tmp.seek(0)
        from reportlab.lib.utils import ImageReader
        c.drawImage(ImageReader(tmp), x, y, width=w, height=h_, mask="auto")

    margin = 18 * mm
    c.setFillColor(colors.HexColor(primary))
    c.rect(0, page_h - 33 * mm, page_w, 33 * mm, stroke=0, fill=1)
    c.setFillColor(colors.white)
    c.setFont("Helvetica-Bold", 18)
    c.drawString(margin, page_h - 17 * mm, record_title_for_design(record)[:36])
    c.setFont("Helvetica", 9)
    c.drawString(margin, page_h - 25 * mm, record_location_for_design(record)[:70])

    cover = photos[0] if photos else placeholder_image((1200, 850))
    draw_pil(cover, margin, page_h - 126 * mm, page_w - 2 * margin, 82 * mm)

    y = page_h - 142 * mm
    c.setFillColor(colors.HexColor(primary))
    c.setFont("Helvetica-Bold", 22)
    c.drawString(margin, y, price_fmt(record.get("price")) if st.session_state.get("smv2_show_price", True) else "Fiyat bilgisi için iletişime geçiniz")
    c.setFillColor(colors.HexColor("#111827"))
    c.setFont("Helvetica-Bold", 14)
    c.drawString(margin, y - 10 * mm, safe(record.get("baslik"))[:62])
    c.setFillColor(colors.HexColor("#4b5563"))
    c.setFont("Helvetica", 9)
    text = c.beginText(margin, y - 19 * mm)
    for line in wrap_plain_text(safe(record.get("aciklama")), 88)[:4]:
        text.textLine(line)
    c.drawText(text)

    # Features
    fy = y - 47 * mm
    c.setFillColor(colors.HexColor(primary))
    c.setFont("Helvetica-Bold", 8)
    x = margin
    for feat in (record.get("features") or [])[:6]:
        box_w = min(38 * mm, max(20 * mm, len(safe(feat)) * 2.2 * mm))
        c.roundRect(x, fy, box_w, 8 * mm, 4 * mm, stroke=0, fill=1)
        c.setFillColor(colors.white)
        c.drawCentredString(x + box_w / 2, fy + 2.6 * mm, safe(feat)[:18])
        c.setFillColor(colors.HexColor(primary))
        x += box_w + 4 * mm
        if x > page_w - margin - 35 * mm:
            break

    # Gallery
    gy = 46 * mm
    thumbs = photos[1:5]
    tw = (page_w - 2 * margin - 6 * mm) / 2
    th = 38 * mm
    for i, ph in enumerate(thumbs):
        px = margin + (i % 2) * (tw + 6 * mm)
        py = gy + (1 - i // 2) * (th + 5 * mm)
        draw_pil(ph, px, py, tw, th)

    # Footer agent
    c.setFillColor(colors.HexColor(soft))
    c.roundRect(margin, 15 * mm, page_w - 2 * margin, 21 * mm, 4 * mm, stroke=0, fill=1)
    c.setFillColor(colors.HexColor("#111827"))
    c.setFont("Helvetica-Bold", 11)
    c.drawString(margin + 8 * mm, 27 * mm, safe(record.get("danisman"), get_profile().get("ad"))[:34])
    c.setFont("Helvetica", 8)
    c.setFillColor(colors.HexColor("#6b7280"))
    c.drawString(margin + 8 * mm, 21 * mm, "Gayrimenkul Danışmanı")
    c.setFont("Helvetica-Bold", 12)
    c.setFillColor(colors.HexColor(primary))
    c.drawRightString(page_w - margin - 8 * mm, 24 * mm, safe(record.get("telefon"), get_profile().get("telefon", ""))[:24])

    c.showPage()
    c.save()
    return buffer.getvalue()


def wrap_plain_text(text: str, width: int) -> List[str]:
    words = safe(text).split()
    lines = []
    cur = ""
    for w in words:
        cand = (cur + " " + w).strip()
        if len(cand) <= width:
            cur = cand
        else:
            if cur:
                lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines or [""]


