def go(stage: str) -> None:
    st.session_state["smv2_stage"] = stage
    safe_rerun()


def reset_flow() -> None:
    for k in [
        "smv2_selected_template_id", "smv2_selected_record", "smv2_selected_photo_keys",
        "smv2_uploaded_photos", "smv2_last_output_bytes", "smv2_last_output_html",
        "smv2_last_output_mime", "smv2_last_output_name",
    ]:
        st.session_state[k] = [] if k.endswith("keys") or k.endswith("photos") else ({} if k.endswith("record") else "")
    st.session_state["smv2_stage"] = "library"
    safe_rerun()


def _render_step_bar_html(current_stage: str) -> str:
    idx = {"library":0,"record_select":1,"details":2,"photo_select":2,"palette_select":2,"manual_edit":2,"preview":3}
    steps = ["Şablon Seç", "İlan Bağla", "Özelleştir", "Oluştur & İndir"]
    cur = idx.get(current_stage, 0)
    parts = []
    for i, lbl in enumerate(steps):
        if i < cur:    nc,lc,ni = "done","done","&#10003;"
        elif i == cur: nc,lc,ni = "active","active",str(i+1)
        else:          nc,lc,ni = "","",str(i+1)
        arr = '<span class="smv2-step-arr-v3">›</span>' if i < len(steps)-1 else ""
        parts.append(f'<div class="smv2-step-item-v3"><div class="smv2-step-num-v3 {nc}">{ni}</div><span class="smv2-step-lbl-v3 {lc}">{h(lbl)}</span></div>{arr}')
    return "".join(parts)


def render_topline(title: str, subtitle: str = "") -> None:
    template = selected_template()
    chip_html = ""
    if template:
        chip_html = f'<span class="smv2-inner-chip blue">{h(template.section)}</span><span class="smv2-inner-chip gold">{h(template.badge)}</span>'
    icon_map = {"İlan":"📍","Fotoğraf":"📷","Renk":"🎨","Ayar":"⚙️","Önizleme":"✨","Düzenle":"✏️","Tasarım":"✨"}
    icon = "▲"
    for kw,ic in icon_map.items():
        if kw in title: icon=ic; break
    step_bar = _render_step_bar_html(st.session_state.get("smv2_stage","library"))
    st.markdown(f"""<div class="smv2-topline-v3"><div class="smv2-inner-header"><div class="smv2-inner-header-left"><div class="smv2-inner-icon">{icon}</div><div><div class="smv2-inner-title">{h(title)}</div><div class="smv2-inner-sub">{h(subtitle)}</div></div></div><div class="smv2-inner-chips">{chip_html}</div></div><div class="smv2-step-bar-v3" style="border-radius:0;border:none;border-top:1px solid #e5e7eb;">{step_bar}</div></div>""", unsafe_allow_html=True)


