def render_record_small(record: Dict[str, Any]) -> str:
    photo = (record.get("photos") or [{}])[0] if record.get("photos") else {}
    img = image_from_photo_item(photo, (500, 360)) if photo else placeholder_image((500, 360), "PORTFÖY")
    uri = image_to_data_uri(fit_cover(img, (500, 330)), "JPEG", 82)
    price_html = f'<div class="smv2-record-price">{h(price_fmt(record.get("price")))}</div>' if st.session_state.get("smv2_show_price", True) else '<div class="smv2-record-price">Fiyat gizli</div>'
    return f"""
<div class="smv2-record-img"><img src="{uri}" style="width:100%;height:100%;object-fit:cover;"></div>
<div>
    <div class="smv2-record-title">{h(short_text(record.get('baslik'), 62))}</div>
    <div class="smv2-record-meta">{h(record_location_for_design(record))}<br>{h(safe(record.get('m2')))} m² · {h(safe(record.get('oda_sayisi')))} · {h(safe(record.get('kat')))}</div>
</div>
<div>{price_html}</div>
"""


