def clean_checkerboard_png_to_data_uri(path: str) -> str:
    """Checkerboard arka planlı PNG'yi kenarlardan flood-fill ile temizleyip data-uri döndürür.

    Şeffaf PNG gerçekten alpha içeriyorsa olduğu gibi kullanır.
    Alpha yoksa veya checkerboard gömülüyse, sadece kenarlara bağlı açık gri/beyaz
    arka planı saydamlaştırır. Böylece iç mockup'lardaki beyaz kartlar korunur.
    """
    try:
        from PIL import Image
        from collections import deque
        import io
        import base64

        img = Image.open(path).convert("RGBA")
        w, h = img.size
        pix = img.load()

        alpha_values = img.getchannel("A").getextrema()
        if alpha_values[0] < 250:
            buf = io.BytesIO()
            img.save(buf, format="PNG")
            return "data:image/png;base64," + base64.b64encode(buf.getvalue()).decode("utf-8")

        def is_bg(x, y):
            r, g, b, a = pix[x, y]
            mx, mn = max(r, g, b), min(r, g, b)
            return a > 0 and mx >= 214 and (mx - mn) <= 22

        visited = bytearray(w * h)
        q = deque()

        def push(x, y):
            idx = y * w + x
            if not visited[idx] and is_bg(x, y):
                visited[idx] = 1
                q.append((x, y))

        for x in range(w):
            push(x, 0)
            push(x, h - 1)
        for y in range(h):
            push(0, y)
            push(w - 1, y)

        while q:
            x, y = q.popleft()
            for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if 0 <= nx < w and 0 <= ny < h:
                    idx = ny * w + nx
                    if not visited[idx] and is_bg(nx, ny):
                        visited[idx] = 1
                        q.append((nx, ny))

        for y in range(h):
            base = y * w
            for x in range(w):
                if visited[base + x]:
                    r, g, b, a = pix[x, y]
                    pix[x, y] = (r, g, b, 0)

        buf = io.BytesIO()
        img.save(buf, format="PNG")
        return "data:image/png;base64," + base64.b64encode(buf.getvalue()).decode("utf-8")
    except Exception:
        import base64
        with open(path, "rb") as f:
            return "data:image/png;base64," + base64.b64encode(f.read()).decode("utf-8")


def _v7_clean_asset_to_image(path: str) -> Image.Image:
    """Hero film görselini temizleyip RGB olarak döndürür."""
    img = Image.open(path).convert("RGBA")
    bg = Image.new("RGBA", img.size, (248, 244, 238, 255))
    # Alpha varsa krem fonda birleştir; checkerboard varsa crop içinde zaten az görünecek.
    bg.alpha_composite(img)
    return bg.convert("RGB")


@st.cache_data(ttl=3600, show_spinner=False)
def _v7_property_photo_bytes(index: int, target_w: int = 1200, target_h: int = 900) -> bytes:
    """Hero film görselinden gerçek gayrimenkul hissi veren kareler kırpar.

    Böylece şablon tasarımları kaybolmaz; render_design_image yine orijinal
    şablon motoruyla çalışır, ama PORTFÖY placeholder yerine daha gerçekçi görsel alır.
    """
    import io

    # 1) Önce kullanıcının assets/sunum_hero_film.png dosyasından kare kırp.
    try:
        hero_path = resolve_asset_path("sunum_hero_film.png")
        if hero_path and os.path.exists(hero_path):
            hero = _v7_clean_asset_to_image(hero_path)
            W, H = hero.size
            boxes = [
                (0.045, 0.255, 0.245, 0.790),
                (0.245, 0.270, 0.430, 0.790),
                (0.435, 0.270, 0.612, 0.790),
                (0.620, 0.270, 0.805, 0.790),
                (0.815, 0.250, 0.965, 0.795),
            ]
            box = boxes[index % len(boxes)]
            crop = hero.crop((
                int(W * box[0]),
                int(H * box[1]),
                int(W * box[2]),
                int(H * box[3]),
            ))
            crop = fit_cover(crop, (target_w, target_h))
            buf = io.BytesIO()
            crop.save(buf, format="JPEG", quality=88)
            return buf.getvalue()
    except Exception:
        pass

    # 2) Asset okunamazsa son çare: daha fotoğraf hissi veren fallback üret.
    img = Image.new("RGB", (target_w, target_h), "#d9e6f2")
    d = ImageDraw.Draw(img)
    # gökyüzü gradient
    for y in range(target_h):
        t = y / max(1, target_h - 1)
        if t < 0.62:
            col = (
                int(210 * (1 - t) + 245 * t),
                int(226 * (1 - t) + 238 * t),
                int(242 * (1 - t) + 222 * t),
            )
        else:
            col = (117, 148, 101)
        d.line((0, y, target_w, y), fill=col)
    # bina/villa
    x0, y0 = int(target_w * 0.23), int(target_h * 0.24)
    x1, y1 = int(target_w * 0.76), int(target_h * 0.69)
    d.rectangle((x0, y0, x1, y1), fill="#b8aa96", outline="#f6f1e8", width=4)
    d.rectangle((x0 + 35, y1 - 115, x0 + 170, y1 + 20), fill="#9a6b43")
    d.rectangle((x0 + 65, y1 - 75, x0 + 110, y1 + 20), fill="#1d2939")
    for i in range(5):
        for j in range(3):
            wx = x0 + 210 + i * 85
            wy = y0 + 55 + j * 82
            d.rectangle((wx, wy, wx + 46, wy + 38), fill="#8fb3cf")
    d.ellipse((target_w - 190, 80, target_w - 115, 155), fill="#f0c96d")
    buf = io.BytesIO()
    img.save(buf, format="JPEG", quality=88)
    return buf.getvalue()


def _v7_property_images_for_template(template: TemplateSpec) -> List[Image.Image]:
    imgs = []
    count = max(1, getattr(template, "max_photos", 1))
    for i in range(count):
        raw = _v7_property_photo_bytes(i, 1200, 900)
        imgs.append(Image.open(io.BytesIO(raw)).convert("RGB"))
    return imgs




